    int64_t stride,
    int64_t dilation
);

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("conv1d_forward_cuda", &conv1d_forward_cuda,
          "Direct 1D convolution (CUDA float32)",
          py::arg("x"), py::arg("weight"), py::arg("bias"),
