CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

// Direct Conv1d kernel: each thread computes one output element (n, co, out_pos)
// Specialized for groups=1, padding=0, float32, NCL layout
__global__ void conv1d_direct_kernel(
    const float* __restrict__ x,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int N, int C_in, int C_out, int L_in, int L_out,
    int kernel_size, int stride, int dilation
) {
    // Grid: (N * C_out, blocks_covering_L_out)
    // Block: (BLOCK_L, 1, 1)
    const int BLOCK_L = 256;
    int nc = blockIdx.x;  // combined (n, co) index
    int n  = nc / C_out;
    int co = nc % C_out;
    int out_start = blockIdx.y * BLOCK_L + threadIdx.x;
    if (out_start >= L_out) return;

    float acc = 0.0f;
    int base_in = out_start * stride;

    // weight layout: [C_out, C_in, K] row-major
    const float* w_co = weight + co * C_in * kernel_size;
    const float* x_n  = x + n * C_in * L_in;

    if (kernel_size == 3) {
        int in0 = base_in;
        int in1 = base_in + dilation;
        int in2 = base_in + 2 * dilation;
        for (int ci = 0; ci < C_in; ++ci) {
            const float* x_nc = x_n + ci * L_in;
            const float* w    = w_co + ci * 3;
            acc += w[0] * x_nc[in0];
            acc += w[1] * x_nc[in1];
            acc += w[2] * x_nc[in2];
        }
    } else {
        for (int k = 0; k < kernel_size; ++k) {
            int in_pos = base_in + k * dilation;
            if (in_pos < 0 || in_pos >= L_in) continue;
            for (int ci = 0; ci < C_in; ++ci) {
                acc += w_co[ci * kernel_size + k] * x_n[ci * L_in + in_pos];
            }
        }
    }

    if (bias) acc += bias[co];
    output[n * C_out * L_out + co * L_out + out_start] = acc;
}

torch::Tensor conv1d_forward_cuda(
    torch::Tensor x,
    torch::Tensor weight,
    c10::optional<torch::Tensor> bias,
    int64_t stride,
    int64_t dilation
) {
    TORCH_CHECK(x.is_cuda(), "x must be CUDA tensor");
    TORCH_CHECK(weight.is_cuda(), "weight must be CUDA tensor");
    TORCH_CHECK(x.dtype() == torch::kFloat32, "x must be float32");
    TORCH_CHECK(weight.dtype() == torch::kFloat32, "weight must be float32");

    int N         = x.size(0);
    int C_in      = x.size(1);
    int L_in      = x.size(2);
    int C_out     = weight.size(0);
    int K         = weight.size(2);
    int L_out     = (L_in - dilation * (K - 1) - 1) / stride + 1;

    auto output = torch::empty({N, C_out, L_out}, x.options());

    const int BLOCK_L = 256;
    dim3 grid(N * C_out, (L_out + BLOCK_L - 1) / BLOCK_L);
    dim3 block(BLOCK_L);

    const float* bias_ptr = nullptr;
    if (bias.has_value() && bias.value().defined()) {
        bias_ptr = bias.value().data_ptr<float>();
    }

    conv1d_direct_kernel<<<grid, block>>>(
        x.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias_ptr,
        output.data_ptr<float>(),
        N, C_in, C_out, L_in, L_out,
        K, (int)stride, (int)dilation
    );

    return output;
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    """
        Performs a standard 1D convolution operation with asymmetric input and a square kernel, potentially dilated and strided.

        Args:
            in_channels (int): Number of channels in the input tensor.
            out_channels (int): Number of channels produced by the convolution.
            kernel_size (int): Size of the square convolution kernel.
            stride (int, optional): Stride of the convolution. Defaults to 1.
            dilation (int, optional): Spacing between kernel elements. Defaults to 1.
            bias (bool, optional): If `True`, adds a learnable bias to the output. Defaults to `False`.
        """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, dilation: int = 1, bias: bool = False):
        super().__init__()
        # <<<IMPROVE:init_body>>>
        self.conv1d = nn.Conv1d(in_channels, out_channels, kernel_size, stride=stride, dilation=dilation, bias=bias)
        # <<<END_IMPROVE>>>

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # <<<IMPROVE:forward_stmt_1>>>
        # Baseline fallback keeps the official PyTorch forward path.
        # After implementing CUDA_CPP_SRC / CUDA_CU_SRC, call _stark_get_extension().your_entrypoint(...).
        """
                Performs the 1D convolution.

                Args:
                    x (torch.Tensor): Input tensor of shape (batch_size, in_channels, length).

                Returns:
                    torch.Tensor: Output tensor of shape (batch_size, out_channels, length_out).
                """
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_2>>>
        conv = self.conv1d
        if (
