            and conv.weight.is_cuda
            and conv.weight.dtype == torch.float32
            and conv.weight.is_contiguous()
            and conv.groups == 1
            and conv.padding[0] == 0
        ):
            bias_val = conv.bias if conv.bias is not None else None
            return _stark_get_extension().conv1d_forward_cuda(
                x, conv.weight, bias_val,
                conv.stride[0], conv.dilation[0]
            )
        return conv(x)
        # <<<END_IMPROVE>>>

