CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

#define COUT_TILE 16
#define BLOCK_OUT_POS 32

__global__ void conv1d_tiled_kernel(
    const float* __restrict__ x,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int N, int C_in, int C_out, int L_in, int L_out,
    int kernel_size, int stride, int dilation
) {
    extern __shared__ float smem[];

    int n = blockIdx.x;
    int co_tile_start = blockIdx.y * COUT_TILE;
    int out_pos_start = blockIdx.z * BLOCK_OUT_POS;

    int tid = threadIdx.x;
    int num_threads = blockDim.x;

    // Load weight tile into shared memory: [COUT_TILE, C_in, K]
    int weight_tile_size = COUT_TILE * C_in * kernel_size;
    for (int idx = tid; idx < weight_tile_size; idx += num_threads) {
        int co_local = idx / (C_in * kernel_size);
        int remainder = idx % (C_in * kernel_size);
        int ci = remainder / kernel_size;
        int k = remainder % kernel_size;

        int co_global = co_tile_start + co_local;
        if (co_global < C_out) {
            smem[idx] = weight[co_global * C_in * kernel_size + ci * kernel_size + k];
        } else {
            smem[idx] = 0.0f;
        }
    }
    __syncthreads();

    // Each thread computes output for multiple (co_local, out_pos) pairs
    for (int idx = tid; idx < COUT_TILE * BLOCK_OUT_POS; idx += num_threads) {
        int co_local = idx / BLOCK_OUT_POS;
        int out_pos_offset = idx % BLOCK_OUT_POS;

        int co_global = co_tile_start + co_local;
        int out_pos = out_pos_start + out_pos_offset;

        if (co_global >= C_out || out_pos >= L_out) continue;

        float acc = 0.0f;
        int base_in = out_pos * stride;

        if (kernel_size == 3) {
            #pragma unroll
            for (int ci = 0; ci < C_in; ++ci) {
                int in0 = base_in;
                int in1 = base_in + dilation;
                int in2 = base_in + 2 * dilation;

                if (in0 >= 0 && in2 < L_in) {
                    float w0 = smem[co_local * C_in * 3 + ci * 3 + 0];
                    float w1 = smem[co_local * C_in * 3 + ci * 3 + 1];
                    float w2 = smem[co_local * C_in * 3 + ci * 3 + 2];

                    float x0 = __ldg(&x[n * C_in * L_in + ci * L_in + in0]);
                    float x1 = __ldg(&x[n * C_in * L_in + ci * L_in + in1]);
                    float x2 = __ldg(&x[n * C_in * L_in + ci * L_in + in2]);

                    acc += w0 * x0 + w1 * x1 + w2 * x2;
                }
            }
        } else {
            for (int k = 0; k < kernel_size; ++k) {
                int in_pos = base_in + k * dilation;
                if (in_pos >= 0 && in_pos < L_in) {
                    #pragma unroll 4
                    for (int ci = 0; ci < C_in; ++ci) {
                        float w = smem[co_local * C_in * kernel_size + ci * kernel_size + k];
                        float x_val = __ldg(&x[n * C_in * L_in + ci * L_in + in_pos]);
                        acc += w * x_val;
                    }
                }
            }
        }

        if (bias) {
            acc += bias[co_global];
        }

        output[n * C_out * L_out + co_global * L_out + out_pos] = acc;
    }
}

torch::Tensor conv1d_tiled_forward_cuda(
    torch::Tensor x,
    torch::Tensor weight,
    c10::optional<torch::Tensor> bias,
    int64_t stride,
    int64_t dilation
) {
    TORCH_CHECK(x.is_cuda(), "x must be CUDA tensor");
    TORCH_CHECK(weight.is_cuda(), "weight must be CUDA tensor");
    TORCH_CHECK(x.dtype() == torch::kFloat32, "x must be float32");
    TORCH_CHECK(weight.dtype() == torch::kFloat32, "weight must be float32");
    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");
    TORCH_CHECK(weight.is_contiguous(), "weight must be contiguous");

    int N = x.size(0);
    int C_in = x.size(1);
    int L_in = x.size(2);
    int C_out = weight.size(0);
    int K = weight.size(2);
    int L_out = (L_in - dilation * (K - 1) - 1) / stride + 1;

    auto output = torch::empty({N, C_out, L_out}, x.options());

    int smem_size = COUT_TILE * C_in * K * sizeof(float);
    int num_threads = 256;

    dim3 grid(
        N,
        (C_out + COUT_TILE - 1) / COUT_TILE,
        (L_out + BLOCK_OUT_POS - 1) / BLOCK_OUT_POS
    );
    dim3 block(num_threads);

    const float* bias_ptr = nullptr;
    if (bias.has_value() && bias.value().defined()) {
        bias_ptr = bias.value().data_ptr<float>();
    }

    conv1d_tiled_kernel<<<grid, block, smem_size>>>(
        x.data_ptr<float>(),
