#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void conv1d_k3s3d4_kernel(
    const float* __restrict__ x,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int B, int C_in, int C_out, int L_in, int L_out
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = B * C_out * L_out;

    if (idx >= total) return;

    int l_out = idx % L_out;
    int c_out = (idx / L_out) % C_out;
    int b = idx / (L_out * C_out);

    const int offsets[3] = {0, 4, 8};

    float sum = 0.0f;
    int l_base = l_out * 3;

    for (int c_in = 0; c_in < C_in; ++c_in) {
        int x_base = b * C_in * L_in + c_in * L_in + l_base;
        int w_base = c_out * C_in * 3 + c_in * 3;

        #pragma unroll
        for (int k = 0; k < 3; ++k) {
            int l_pos = l_base + offsets[k];
            if (l_pos < L_in) {
                sum += __ldg(&x[x_base + offsets[k]]) * __ldg(&weight[w_base + k]);
            }
        }
    }

    if (bias != nullptr) {
        sum += __ldg(&bias[c_out]);
    }

    output[idx] = sum;
